from gurobipy import Model, GRB, quicksum

def build_and_solve():
    shelf_records = [r for r in LEGACY_RECORDS if r['source'].endswith('capacity.csv')]
    shelf_ids = []
    shelf_caps = []
    for r in shelf_records:
        shelf_ids.append(r['values']['ShelfID'])
        shelf_caps.append(int(r['values']['Capacity']))
    if len(shelf_ids) != 10:
        raise ValueError('Expected 10 shelves, got %d' % len(shelf_ids))
    prod_records = [r for r in LEGACY_RECORDS if r['source'].endswith('products.csv')]
    prod_ids = []
    prod_vals = []
    prod_wgts = []
    for r in prod_records:
        prod_ids.append(r['values']['ProductName'])
        prod_vals.append(int(r['values']['Value']))
        prod_wgts.append(int(r['values']['Weight']))
    if len(prod_ids) != 20:
        raise ValueError('Expected 20 products, got %d' % len(prod_ids))
    m = Model()
    m.Params.MIPGap = 0.0001
    x_vars = m.addVars(shelf_ids, prod_ids, vtype=GRB.INTEGER, lb=0, name='')
    m.setObjective(quicksum((prod_vals[j] * x_vars[shelf_ids[i], prod_ids[j]] for i in range(len(shelf_ids)) for j in range(len(prod_ids)))), GRB.MAXIMIZE)
    for i, shelf in enumerate(shelf_ids):
        m.addConstr(quicksum((prod_wgts[j] * x_vars[shelf, prod_ids[j]] for j in range(len(prod_ids)))) <= shelf_caps[i], name='cap_%s' % shelf)
    for i in range(len(shelf_ids)):
        for j in range(len(prod_ids)):
            if prod_vals[j] is None or prod_wgts[j] is None or shelf_caps[i] is None:
                raise ValueError('Missing data for shelf %s, product %s' % (shelf_ids[i], prod_ids[j]))
    m.optimize()
    if m.Status == GRB.OPTIMAL:
        print('ObjVal', m.ObjVal)
        for i in shelf_ids:
            for j in prod_ids:
                v = x_vars[i, j]
                print(v.VarName, v.X)
    else:
        print('Status', m.Status)
    return m
m = build_and_solve()